import os,re,json
root="."
absent=[l.strip() for l in open("/tmp/absent.txt") if l.strip()]
absent=[m for m in absent if not m.endswith("H1BaseFieldInvariance")]

declre=re.compile(r'^\s*(?:@\[[^\]]*\]\s*)?(?:noncomputable\s+|private\s+|protected\s+|scoped\s+)*(?:theorem|lemma|def|instance|abbrev|structure|class)\s+([A-Za-z_][\w.\']*)')
nsre=re.compile(r'^\s*(namespace|end)\s+([\w.\']+)')

def qualified(m):
    """return set of fully-qualified decl names"""
    f=os.path.join(root,m.replace('.','/')+'.lean')
    stack=[];out=set()
    for line in open(f):
        n=nsre.match(line)
        if n:
            if n.group(1)=="namespace": stack.append(n.group(2))
            elif stack and stack[-1]==n.group(2): stack.pop()
            continue
        d=declre.match(line)
        if d:
            out.add(".".join(stack+[d.group(1)]))
    return out

GENERIC={'of','mk','mul','inv','ext','res','map','one','congr','pullback','id','add','zero','comp','trans','symm','val','coe','left','right','hom','presentation','picClass'}
qual={m:qualified(m) for m in absent}
# name (as written, possibly partially qualified) -> modules.  Use last1 and last2 segments.
index={}
for m,names in qual.items():
    for q in names:
        segs=q.split('.')
        keys=set()
        keys.add(q)
        if len(segs)>=2: keys.add(".".join(segs[-2:]))
        if segs[-1] not in GENERIC and len(segs[-1])>=6: keys.add(segs[-1])
        for k in keys: index.setdefault(k,set()).add(m)

def code(m):
    src=open(os.path.join(root,m.replace('.','/')+'.lean')).read()
    src=re.sub(r'/-.*?-/',' ',src,flags=re.S)
    src=re.sub(r'--[^\n]*',' ',src)
    src=re.sub(r'^import[^\n]*','',src,flags=re.M)
    return src

start="AlgebraicJacobian.Cohomology.H1BaseFieldInvariance"
needed={}; seen={start}; frontier=[start]
while frontier:
    m=frontier.pop()
    src=code(m)
    toks=set(re.findall(r"[A-Za-z_][A-Za-z0-9_.\']*",src))
    for k,mods in index.items():
        if k in toks:
            for om in mods:
                if om==m: continue
                needed.setdefault(om,{}).setdefault(m,set()).add(k)
                if om not in seen: seen.add(om); frontier.append(om)

lb=sorted(needed); tot=0
print(f"LOAD-BEARING: {len(lb)} of {len(absent)}")
for m in lb:
    n=sum(1 for _ in open(os.path.join(root,m.replace('.','/')+'.lean'))); tot+=n
    via=sorted(needed[m]); print(f"  {n:5}  {m}")
    for v in via[:3]:
        print(f"          <- {v.replace('AlgebraicJacobian.','')} : {sorted(needed[m][v])[:6]}")
print("LB lines:",tot)
print("\nNOT REFERENCED (bundling):")
for m in sorted(set(absent)-set(needed)):
    n=sum(1 for _ in open(os.path.join(root,m.replace('.','/')+'.lean')))
    print(f"  {n:5}  {m}")
EOF
